import type { FeedConfig, FeedItem, ScraperHelpers } from "../../types.js"

export async function fetchFeed(config: FeedConfig, helpers: ScraperHelpers): Promise<FeedItem[]> {
  const resp = await fetch(config.url)
  if (!resp.ok) {
    throw new Error(`Failed to fetch ${config.url}: ${resp.status} ${resp.statusText}`)
  }
  const markdown = await resp.text()

  // Split into version sections on "## " headings
  const sections = markdown.split(/\n(?=## )/)
  const items: FeedItem[] = []
  const now = new Date()

  for (const section of sections) {
    if (!section.startsWith("## ")) continue

    const lines = section.split("\n")
    const versionLine = lines[0].replace(/^## /, "").trim()

    // Extract version number like 2.1.144
    const versionMatch = versionLine.match(/^(\d+\.\d+\.\d+)/)
    if (!versionMatch) continue

    const version = versionMatch[1]
    const bodyLines = lines.slice(1).filter((l) => l.trim().length > 0 && l.startsWith("- "))

    if (bodyLines.length === 0) continue

    // Convert Markdown list to HTML
    let html = "<ul>\n"
    for (const line of bodyLines) {
      let item = line.replace(/^- /, "").trim()
      // **bold** → <strong>
      item = item.replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>")
      // `code` → <code>
      item = item.replace(/`([^`]+)`/g, "<code>$1</code>")
      html += `  <li>${item}</li>\n`
    }
    html += "</ul>"

    const id = `claude-code-v${version}`
    const title = `Claude Code v${version}`
    const url = `https://github.com/anthropics/claude-code/releases/tag/v${version}`

    // Assign descending dates since the changelog has no explicit dates
    const date = new Date(now)
    date.setDate(date.getDate() - items.length)
    const publishedAt = date.toISOString().split("T")[0] + "T00:00:00.000Z"

    items.push({
      id,
      title,
      url,
      publishedAt,
      contentHtml: html,
      source: config.slug,
    })
  }

  return items
}
